output_pos = (15, 4)
output_size = (4, 4)

# Get cells in the output region
output_region_cells = []
for r in range(output_pos[0], output_pos[0] + output_size[0]):
    for c in range(output_pos[1], output_pos[1] + output_size[1]):
        if demo1_grid[r, c] == 1:
            output_region_cells.append((r, c))

print(f"Output region cells: {output_region_cells}")

# Now find all components
def find_components(grid, val):
    visited = np.zeros_like(grid, dtype=bool)
    components = []

    def flood_fill(start, color):
        region = [tuple(start)]
        stack = [start]
        while stack:
            r, c = stack.pop()
            if 0 <= r < grid.shape[0] and 0 <= c < grid.shape[1]:
                if grid[r, c] == color and not visited[r, c]:
                    visited[r, c] = True
                    region.append(tuple((r, c)))
                    stack.extend([(r+1, c), (r-1, c), (r, c+1), (r, c-1)])
        return region

    for r in range(grid.shape[0]):
        for c in range(grid.shape[1]):
            if grid[r, c] == val and not visited[r, c]:
                region = flood_fill((r, c), val)
                if len(region) > 0:
                    components.append(region)
    return components

