def find_all_components(grid, val):
    visited = [[False for _ in range(grid.shape[1])] for _ in range(grid.shape[0])]
    components = []

    def flood_fill_from_cell(start_cells):
        component = set()
        stack = start_cells
        local_visited = set()

        while stack:
            cr, cc = stack.pop()
            if 0 <= cr < grid.shape[0] and 0 <= cc < grid.shape[1]:
                if grid[cr, cc] == val and (cr, cc) not in local_visited:
                    local_visited.add((cr, cc))
                    component.add((cr, cc))
                    for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
                        nr, nc = cr + dr, cc + dc
                        stack.append((nr, nc))
        return sorted(list(component))

    for r in range(grid.shape[0]):
        for c in range(grid.shape[1]):
            if grid[r, c] == val and not visited[r][c]:
                comp = flood_fill_from_cell([(r, c)])
                if len(comp) > 0:
                    components.append(comp)
    return components

