        return
    try:
        items = os.listdir(path)
        for item in items:
            full_path = os.path.join(path, item)
            is_dir = os.path.isdir(full_path)
            indent = " " * level
            print(f"{indent}{prefix}{item}/" if is_dir else f"{indent}{item}")
            if is_dir:
                print_tree(full_path, level + 1, max_depth, prefix + "  ")
